-- Conformed geography: nation and region flattened into one reusable model.
-- Customer and supplier both point to a nation, so the hierarchy is resolved
-- once here instead of being re-joined in every Gold dimension.

-- Columns dropped from brz_nation / brz_region:
--   n_comment, r_comment         free-text filler generated by TPC-H, no analytical value
--   n_regionkey                  redundant after the join: same value as region_id
--   _loaded_at, _batch_id,
--   _source_relation             25-row static reference data, no deduplication history needed downstream

with nation as (
    {{ deduplicate(ref('brz_nation'), partition_by=['n_nationkey']) }}
),

region as (
    {{ deduplicate(ref('brz_region'), partition_by=['r_regionkey']) }}
)

select
    nation.n_nationkey::varchar        as nation_id,
    {{ clean_label('nation.n_name') }}::varchar as nation_name,
    region.r_regionkey::varchar        as region_id,
    {{ clean_label('region.r_name') }}::varchar as region_name
from nation
left join region
    on nation.n_regionkey = region.r_regionkey
